const input = $json ?? {};

const execution =
  input.execution &&
  typeof input.execution === 'object'
    ? input.execution
    : {};

const workflow =
  input.workflow &&
  typeof input.workflow === 'object'
    ? input.workflow
    : {};

const error =
  execution.error &&
  typeof execution.error === 'object'
    ? execution.error
    : (
        input.error &&
        typeof input.error === 'object'
          ? input.error
          : {}
      );

const firstNonEmpty = (...values) => {
  for (const value of values) {
    if (
      value !== undefined &&
      value !== null &&
      String(value).trim() !== ''
    ) {
      return value;
    }
  }

  return null;
};

const rawHttpStatus = firstNonEmpty(
  error.httpStatus,
  error.httpCode,
  error.statusCode,
  error.status,
  error.response?.status,
  error.cause?.statusCode
);

let httpStatus = null;

if (rawHttpStatus !== null) {
  const parsed = Number(rawHttpStatus);

  if (
    Number.isInteger(parsed) &&
    parsed >= 100 &&
    parsed <= 599
  ) {
    httpStatus = parsed;
  }
}

const errorMessageRaw = firstNonEmpty(
  error.message,
  error.description,
  input.message,
  'Unknown workflow failure'
);

const errorMessage =
  String(errorMessageRaw).slice(0, 4000);

const stackRaw =
  typeof error.stack === 'string'
    ? error.stack
    : null;

const errorStack =
  stackRaw
    ? stackRaw.slice(0, 8000)
    : null;

const executionId =
  firstNonEmpty(
    execution.id,
    input.executionId,
    input.execution_id
  );

const workflowId =
  firstNonEmpty(
    workflow.id,
    input.workflowId,
    input.workflow_id
  );

const workflowName =
  firstNonEmpty(
    workflow.name,
    input.workflowName,
    input.workflow_name,
    'Unknown Workflow'
  );

const nodeName =
  firstNonEmpty(
    execution.lastNodeExecuted,
    error.node?.name,
    error.nodeName,
    input.node_name,
    'Unknown Node'
  );

const occurredAtRaw =
  firstNonEmpty(
    error.timestamp,
    input.timestamp,
    null
  );

let occurredAt =
  new Date().toISOString();

if (occurredAtRaw !== null) {
  const rawString =
    String(occurredAtRaw).trim();

  // Unix seconds or milliseconds
  if (/^\d+$/.test(rawString)) {
    let numericTimestamp =
      Number(rawString);

    // Convert Unix seconds to milliseconds when needed
    if (numericTimestamp < 1e12) {
      numericTimestamp *= 1000;
    }

    const parsedDate =
      new Date(numericTimestamp);

    if (
      !Number.isNaN(
        parsedDate.getTime()
      )
    ) {
      occurredAt =
        parsedDate.toISOString();
    }
  } else {
    // ISO/date-like timestamp
    const parsedDate =
      new Date(rawString);

    if (
      !Number.isNaN(
        parsedDate.getTime()
      )
    ) {
      occurredAt =
        parsedDate.toISOString();
    }
  }
}

return {
  error_context: {
    source:
      'n8n_error_trigger',

    execution_id:
      executionId !== null
        ? String(executionId)
        : null,

    execution_url:
      firstNonEmpty(
        execution.url,
        input.executionUrl
      ),

    retry_of_execution_id:
      firstNonEmpty(
        execution.retryOf,
        execution.retry_of,
        input.retryOf
      ),

    workflow_id:
      workflowId !== null
        ? String(workflowId)
        : null,

    workflow_name:
      String(workflowName),

    node_name:
      String(nodeName),

    execution_mode:
      firstNonEmpty(
        execution.mode,
        input.mode,
        'unknown'
      ),

    error_name:
      firstNonEmpty(
        error.name,
        error.type,
        'WorkflowError'
      ),

    error_code:
      firstNonEmpty(
        error.code,
        error.errorCode,
        null
      ),

    error_message:
      errorMessage,

    http_status:
      httpStatus,

    error_stack:
      errorStack,

    occurred_at:
      occurredAt,

    normalized_at:
      new Date().toISOString(),

    schema_version:
      '1.0'
  },

  workflow_stage:
    'error_normalized'
};

const data = $json;

const errorContext =
  data.error_context ?? {};

const now =
  new Date();

const randomPart =
  Math.random()
    .toString(36)
    .substring(2, 10)
    .toUpperCase();

const incidentId =
  `INC-${now.getTime()}-${randomPart}`;

const executionPart =
  errorContext.execution_id ??
  'NOEXEC';

const nodePart =
  String(
    errorContext.node_name ??
    'UNKNOWN'
  )
    .replace(/[^a-zA-Z0-9_-]/g, '_')
    .slice(0, 80);

const occurredPart =
  String(
    errorContext.occurred_at ??
    now.toISOString()
  )
    .replace(/[^0-9A-Za-z]/g, '')
    .slice(0, 30);

const idempotencyKey =
  `ERR-${executionPart}-${nodePart}-${occurredPart}`;

const retryOf =
  errorContext.retry_of_execution_id ??
  null;

return {
  ...data,

  incident: {
    incident_id:
      incidentId,

    idempotency_key:
      idempotencyKey,

    source_execution_id:
      errorContext.execution_id ??
      null,

    retry_of_execution_id:
      retryOf,

    attempt:
      retryOf
        ? 2
        : 1,

    incident_status:
      'opened',

    created_at:
      now.toISOString(),

    incident_version:
      '1.0'
  },

  workflow_stage:
    'incident_created'
};

const data = $json;

const ctx =
  data.error_context ?? {};

const message =
  String(
    ctx.error_message ?? ''
  ).toLowerCase();

const nodeName =
  String(
    ctx.node_name ?? ''
  ).toLowerCase();

const errorName =
  String(
    ctx.error_name ?? ''
  ).toLowerCase();

const errorCode =
  String(
    ctx.error_code ?? ''
  ).toLowerCase();

const httpStatus =
  Number.isInteger(ctx.http_status)
    ? ctx.http_status
    : null;

const containsAny = (
  text,
  patterns
) =>
  patterns.some(
    pattern =>
      text.includes(pattern)
  );

const combined =
  `${message} ${nodeName} ${errorName} ${errorCode}`;

let errorType =
  'unknown';

let severity =
  'high';

let retryable =
  false;

let recoveryStrategy =
  'manual_review';

let classificationReason =
  'No approved deterministic classification rule matched.';

// Authentication / permission failures
if (
  httpStatus === 401 ||
  httpStatus === 403 ||
  containsAny(combined, [
    'unauthorized',
    'forbidden',
    'authentication',
    'invalid credential',
    'credentials',
    'permission denied',
    'access denied'
  ])
) {
  errorType =
    'authentication_or_permission';

  severity =
    'high';

  retryable =
    false;

  recoveryStrategy =
    'manual_intervention';

  classificationReason =
    'Authentication or permission failures must not be automatically retried.';
}

// Rate limiting
else if (
  httpStatus === 429 ||
  containsAny(combined, [
    'rate limit',
    'too many requests'
  ])
) {
  errorType =
    'rate_limit';

  severity =
    'medium';

  retryable =
    true;

  recoveryStrategy =
    'retry_with_backoff';

  classificationReason =
    'Rate-limit failures may recover after controlled backoff.';
}

// Timeout
else if (
  httpStatus === 408 ||
  httpStatus === 504 ||
  containsAny(combined, [
    'timeout',
    'timed out',
    'etimedout'
  ])
) {
  errorType =
    'timeout';

  severity =
    'medium';

  retryable =
    true;

  recoveryStrategy =
    'retry_with_backoff';

  classificationReason =
    'Timeout failures are potentially transient.';
}

// Network / upstream service
else if (
  (
    httpStatus !== null &&
    httpStatus >= 500 &&
    httpStatus <= 599
  ) ||
  containsAny(combined, [
    'econnreset',
    'econnrefused',
    'enotfound',
    'network',
    'socket hang up',
    'service unavailable',
    'bad gateway'
  ])
) {
  errorType =
    'network_or_upstream';

  severity =
    'high';

  retryable =
    true;

  recoveryStrategy =
    'retry_with_backoff';

  classificationReason =
    'Network or upstream-service failures may be transient.';
}

// Database-specific failures
else if (
  containsAny(combined, [
    'postgres',
    'postgresql',
    'database',
    'sql',
    'relation ',
    'column ',
    'constraint'
  ]) ||
  nodeName.includes('db |')
) {
  const permanentDbFailure =
    containsAny(combined, [
      'permission denied',
      'does not exist',
      'syntax error',
      'violates',
      'constraint',
      'duplicate key',
      'invalid input syntax'
    ]);

  errorType =
    permanentDbFailure
      ? 'database_query_or_integrity'
      : 'database_connectivity';

  severity =
    'high';

  retryable =
    !permanentDbFailure;

  recoveryStrategy =
    permanentDbFailure
      ? 'manual_intervention'
      : 'retry_with_backoff';

  classificationReason =
    permanentDbFailure
      ? 'Database query, permission, or integrity failures require correction rather than blind retry.'
      : 'Database connectivity failures may be transient.';
}

// Validation / governed rejection
else if (
  containsAny(combined, [
    'validation',
    'invalid payload',
    'schema',
    'not allowed',
    'unsupported',
    'rejected'
  ]) ||
  nodeName.includes('val |')
) {
  errorType =
    'validation_or_contract';

  severity =
    'medium';

  retryable =
    false;

  recoveryStrategy =
    'safe_rejection';

  classificationReason =
    'Validation and contract failures should fail safely rather than retry.';
}

// AI / model provider
else if (
  containsAny(nodeName, [
    'ai |',
    'model',
    'openai',
    'llm'
  ]) ||
  containsAny(combined, [
    'model provider',
    'language model',
    'llm'
  ])
) {
  errorType =
    'ai_provider';

  severity =
    'high';

  retryable =
    false;

  recoveryStrategy =
    'provider_fallback_review';

  classificationReason =
    'Unclassified AI-provider failures require controlled provider/fallback handling.';
}

// Delivery layer
else if (
  containsAny(nodeName, [
    'del |',
    'slack',
    'webhook',
    'form',
    'email'
  ])
) {
  errorType =
    'delivery';

  severity =
    'medium';

  retryable =
    false;

  recoveryStrategy =
    'delivery_fallback_review';

  classificationReason =
    'Delivery failures require adapter-aware recovery rather than blind retry.';
}

return {
  ...data,

  error_classification: {
    error_type:
      errorType,

    severity,

    retryable,

    recovery_strategy:
      recoveryStrategy,

    classification_reason:
      classificationReason,

    classifier_type:
      'deterministic_rules',

    classifier_version:
      '1.0',

    classified_at:
      new Date().toISOString()
  },

  workflow_stage:
    'error_classified'
};

const response =
  $json ?? {};

const original =
  $('SYS-008 | SYS | Retry Backoff')
    .item.json ?? {};

const statusCode =
  Number(
    response.statusCode ??
    response.status ??
    0
  );

const body =
  response.body &&
  typeof response.body === 'object'
    ? response.body
    : response;

const retryExecutionId =
  body.id !== undefined &&
  body.id !== null
    ? String(body.id)
    : null;

const retryOf =
  body.retryOf !== undefined &&
  body.retryOf !== null
    ? String(body.retryOf)
    : null;

const mode =
  body.mode !== undefined &&
  body.mode !== null
    ? String(body.mode)
    : null;

const hasSuccessStatus =
  statusCode === 200 ||
  (
    statusCode === 0 &&
    retryExecutionId !== null
  );

const hasRetryId =
  retryExecutionId !== null &&
  retryExecutionId.trim() !== '';

const hasParentExecution =
  retryOf !== null &&
  retryOf.trim() !== '';

const modeValid =
  mode === null ||
  mode === 'retry';

const isValid =
  hasSuccessStatus &&
  hasRetryId &&
  hasParentExecution &&
  modeValid;

const validationErrors = [];

if (!hasSuccessStatus) {
  validationErrors.push(
    `Unexpected retry API status: ${statusCode || 'unknown'}`
  );
}

if (!hasRetryId) {
  validationErrors.push(
    'Retry API response did not contain a new execution ID.'
  );
}

if (!hasParentExecution) {
  validationErrors.push(
    'Retry API response did not contain retryOf.'
  );
}

if (!modeValid) {
  validationErrors.push(
    `Unexpected execution mode: ${mode}`
  );
}

return {
  ...original,

  retry_dispatch: {
    is_valid:
      isValid,

    http_status:
      statusCode || null,

    retry_execution_id:
      retryExecutionId,

    retry_of_execution_id:
      retryOf,

    execution_mode:
      mode,

    validation_errors:
      validationErrors,

    validated_at:
      new Date().toISOString(),

    validator_version:
      '1.1'
  },

  workflow_stage:
    isValid
      ? 'retry_dispatched'
      : 'retry_dispatch_failed'
};

const data =
  $json ?? {};

const classification =
  data.error_classification ?? {};

const incident =
  data.incident ?? {};

const retryDispatch =
  data.retry_dispatch ?? null;

const attempt =
  Number(
    data.attempt ??
    incident.attempt ??
    1
  );

const retryable =
  classification.retryable === true ||
  data.retryable === true;

const severity =
  String(
    data.severity ??
    classification.severity ??
    'high'
  );

let reason =
  'manual_intervention_required';

let reasonDescription =
  'Incident requires controlled manual intervention.';

if (!retryable) {
  reason =
    'non_retryable_failure';

  reasonDescription =
    'The deterministic classifier marked this failure as non-retryable.';
}
else if (attempt >= 3) {
  reason =
    'retry_budget_exhausted';

  reasonDescription =
    'The incident reached the maximum permitted total of three attempts.';
}
else if (
  retryDispatch &&
  retryDispatch.is_valid === false
) {
  reason =
    'retry_dispatch_failed';

  reasonDescription =
    'The approved retry could not be successfully dispatched.';
}

const priority =
  severity === 'critical'
    ? 'urgent'
    : severity === 'high'
      ? 'high'
      : 'normal';

return {
  ...data,

  escalation: {
    reason,

    reason_description:
      reasonDescription,

    priority,

    alert_required:
      true,

    dead_letter_required:
      true,

    current_attempt:
      attempt,

    max_attempts:
      3,

    prepared_at:
      new Date().toISOString(),

    escalation_version:
      '1.0'
  },

  workflow_stage:
    'escalation_prepared'
};

