const response =
  $json ?? {};

const original =
  $('SYS-012 | SYS | Prepare Escalation')
    .item.json ?? {};

const responseError =
  response.error ??
  response.message?.error ??
  null;

const messageTs =
  response.ts ??
  response.message?.ts ??
  null;

const responseOk =
  response.ok === true ||
  messageTs !== null;

const sent =
  responseOk &&
  !responseError;

return {
  ...original,

  escalation: {
    ...original.escalation,

    alert: {
      channel:
        'slack',

      status:
        sent
          ? 'sent'
          : 'failed',

      message_ts:
        messageTs
          ? String(messageTs)
          : null,

      error:
        responseError
          ? String(responseError).slice(0, 500)
          : null,

      attempted_at:
        new Date().toISOString()
    }
  },

  workflow_stage:
    sent
      ? 'escalation_alert_sent'
      : 'escalation_alert_failed'
};

const REDACTED = '[REDACTED]';

function redactSensitive(value) {
  if (value === null || value === undefined) {
    return '';
  }

  let text = String(value);

  // Authorization headers
  text = text.replace(
    /\b(authorization\s*[:=]\s*)(bearer|basic)\s+[A-Za-z0-9\-._~+/]+=*/gi,
    '$1$2 [REDACTED]'
  );

  // Common secret-bearing key/value patterns
  text = text.replace(
    /\b(api[_-]?key|apikey|access[_-]?token|refresh[_-]?token|token|password|passwd|pwd|secret|client[_-]?secret)\b\s*[:=]\s*(["']?)[^\s,;}"']+\2/gi,
    '$1=[REDACTED]'
  );

  // Credentials embedded inside URLs:
  // credential-bearing database URL example
  // credential-bearing HTTP URL example
  text = text.replace(
    /([a-z][a-z0-9+.-]*:\/\/[^:\s/@]+:)[^@\s/]+(@)/gi,
    '$1[REDACTED]$2'
  );

  // JWT-like tokens
  text = text.replace(
    /\beyJ[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}\b/g,
    '[REDACTED_JWT]'
  );

  // Common provider token formats
  text = text.replace(
    /\b(sk-[A-Za-z0-9_-]{12,}|gsk_[A-Za-z0-9_-]{12,}|xox[baprs]-[A-Za-z0-9-]{10,})\b/g,
    '[REDACTED_TOKEN]'
  );

  // Bound outbound diagnostic size.
  if (text.length > 1500) {
    text = text.slice(0, 1500) + '…[TRUNCATED]';
  }

  return text;
}

const rawErrorMessage =
  $json.error_message ??
  $json.error_context?.error_message ??
  '';

const rawEscalationReason =
  $json.escalation?.reason ??
  'Automatic recovery exhausted';

return {
  json: {
    incident_id:
      $json.incident_id ??
      $json.incident?.incident_id ??
      null,

    request_id:
      $json.request_id ??
      null,

    correlation_id:
      $json.correlation_id ??
      null,

    workflow_name:
      $json.workflow_name ??
      $json.error_context?.workflow_name ??
      'unknown',

    workflow_id:
      $json.workflow_id ??
      null,

    execution_id:
      $json.execution_id ??
      $json.error_context?.execution_id ??
      'unknown',

    node_name:
      $json.node_name ??
      $json.error_context?.node_name ??
      'unknown',

    environment:
      $json.environment ??
      'unknown',

    severity:
      $json.severity ??
      $json.error_classification?.severity ??
      'unknown',

    error_type:
      $json.error_type ??
      $json.error_classification?.error_type ??
      'unknown',

    error_code:
      $json.error_code ??
      null,

    http_status:
      $json.http_status ??
      null,

    attempt:
      $json.attempt ??
      $json.incident?.attempt ??
      0,

    retryable:
      $json.retryable ??
      false,

    safe_escalation_reason:
      redactSensitive(rawEscalationReason) ||
      'Automatic recovery exhausted',

    safe_error_message:
      redactSensitive(rawErrorMessage) ||
      'Error details unavailable'
  }
};
